 var ranges;
 let seed = Math.random() * 1247;
 var mySize, margin, grad;
 let str_wei = 0;

 // colors
 let darkColors = "281914-1a1a1a-202020-242e30".split("-").map((a) => "#" + a);
 let lightColors = "fef9fb-fafdff-ffffff-fcfbf4-f9f8f6".split("-").map((a) => "#" + a);
 let colors1 = "8c75ff-c553d2-47c465-2788f5-321063-f21252-8834f1-c4dd92-184fd3-f9fee2-2E294E-541388-F1E9DA-FFD400-bf2e72-e9baaa-ffa07a-164555-ffe1d0-acd9e7-4596c7-6d8370-e45240-21d3a4-3303f9-cd2220-173df6-244ca8-a00360-b31016".split("-").map((a) => "#" + a);
 //let colors_cyber = "ee0cf2-352ef2-1df252-f2e41d".split("-").map((a) => "#" + a);
 let color1, color2;
 let colorselect = [];

 let unit_x, unit_y;
 let count;
 let mods = [];
 let backwardsMods = [];
 let loop_num = 0;

let song;

function preload() {
	song = loadSound('https://openprocessing.org/sketch/1764006/files/german-radio-tuning.mp3');
}

 function setup() {
 	// pixelDensity(5);
 	randomSeed(seed);
 	margin = 0;
 	createCanvas(windowWidth, windowHeight);

	song.loop();
	 song.play();

 	colorselect[0] = random(darkColors);
 	colorselect[1] = random(colors1);
 	colorselect[2] = random(colors1);
 	colorselect[3] = random(colors1);
 	colorselect[4] = random(colors1);
 	colorselect[5] = random(lightColors);
 	let num = 1;
 	unit_x = width / num;
 	unit_y = height / num;

 	noStroke();
 	let wideCount = width / unit_x + 0;
 	let highCount = height / unit_y + 1;
 	count = wideCount * highCount;

 	let index = 0;
 	for (let y = 0; y < highCount; y++) {
 		for (let x = 0; x < wideCount; x++) {
 			mods[index++] = new Module(
 				x * unit_x,
 				y * unit_y,
 				0,
 				unit_y * -0.15,
 				1,
 				1 * unit_x
 			);
 		}
 	} 

	let index2 = 0;
	 for(let j = 0; j < highCount; j++) {
			for(let k = 0; k < wideCount; k++) {
				backwardsMods[index2++] = new backwardsModule(
					k*unit_x,
					j*unit_y,
					0,
					unit_y * 0.2,
					1,
					1 * unit_x
					);
			}
	 }

//	let filter1 = new makeFilter();
 	background(random(colorselect));
 }

 function draw() {
 	randomSeed(seed);
 	// background("#202020");
 	for (let i = 0; i < count; i++) {
 		mods[i].update();
 		mods[i].draw();
		backwardsMods[i].update();
		backwardsMods[i].draw();
 		// image(overAllTexture, 0, 0);
 		// 	noFill();
 		// 	stroke("#202020");
 		// 	strokeWeight(margin);
 		// 	rectMode(CORNER);
 		// 	rect(0, 0, width, height);
 }

 }

 class Module {
 	constructor(xOff, yOff, x, y, speed, unit) {
 		this.xOff = xOff;
 		this.yOff = yOff;
 		this.x = x;
 		this.y = y;
 		this.speed = speed * 2;
 		this.unit = unit;
 		this.xDir = 1;
 		this.yDir = 1;
 	} 

 	// Custom method for updating the variables
 	update() {
 		this.x = this.x + this.speed * this.xDir;
 		// this.y = this.y + this.speed * this.yDir;
 		if (this.x >= this.unit+100 || this.x <= -100) {
 			this.xDir *= -1;
 			this.x = this.x + 1 * this.xDir;
 			this.y = this.y + 1 * this.yDir;
 			loop_num++;
 		}
 		if (this.y >= this.unit || this.y <= 0) {
 			this.yDir *= -1;
 			this.y = this.y + 1 * this.yDir;
 		}
 	}

 	// Custom method for drawing the object
 	draw() {
 		noStroke();
 		fill(str(random(colorselect)) + "80");

 		//shadow & highlight
 		drawingContext.shadowColor = "#ffffff33";
 		drawingContext.shadowOffsetX = -1;
 		drawingContext.shadowOffsetY = -1;
 		drawingContext.shadowBlur = 0;
 		drawingContext.shadowColor = "#2f2f2f1a";
 		drawingContext.shadowOffsetX = 1;
 		drawingContext.shadowOffsetY = 1;
 		drawingContext.shadowBlur = 0;

 		//parameters
 		let y_size = this.unit * noise(random(), frameCount * 0.01);
 		let rio = 0.25;
 		let y_plus = random(0, y_size * rio)

 		//mountain
 		stroke(random(darkColors));
 		strokeWeight(0.25);
 		push();
 		translate(this.xOff + this.x, this.yOff - this.y);
 		rotate(PI);
 		//gradient
 		let color_a = random(colorselect);
 		grad = drawingContext.createLinearGradient(0, 0, 0, y_size);
 		grad.addColorStop(0, str(color_a) + "1a");
 		grad.addColorStop(0.45, str(random(colorselect)) + "40");
 		grad.addColorStop(1, str(random(colorselect)) + "80");
 		drawingContext.fillStyle = grad;
 		// rectMode(CENTER);
 		// randomSeed(seed);
 		arc(0, y_plus, y_size / 10, y_size, 0, PI);
 		pop();

 		//reflection
 		noStroke();
 		push();
 		translate(-10 + this.xOff + this.x, this.yOff - this.y);
 		let color_b = random(colorselect);
 		grad = drawingContext.createLinearGradient(0, 0, 0, y_size-y_plus);
 		grad.addColorStop(0, str(color_b) + "1a");
 		grad.addColorStop(0.25+random(-0.1,0.1), str(random(colorselect)) + "00");
 		drawingContext.fillStyle = grad;
 		rect(0, -y_plus, y_size / 10, y_size);
 		pop();


 		drawingContext.shadowColor = "#ffffff00";
 		drawingContext.shadowOffsetX = -1;
 		drawingContext.shadowOffsetY = -1;
 		drawingContext.shadowBlur = 0;
 		drawingContext.shadowColor = "#2f2f2f00";
 		drawingContext.shadowOffsetX = 1;
 		drawingContext.shadowOffsetY = 1;
 		drawingContext.shadowBlur = 0;
 		// //circle line
 		// noStroke();
 		// push();
 		// translate(this.xOff + this.x, this.yOff - this.y);
 		// grad = drawingContext.createLinearGradient(0, -y_size / 10 - y_plus, 0, y_size / 10 - y_plus);
 		// grad.addColorStop(0, str(color_a) + "00");
 		// grad.addColorStop(0.25, str(color_a) + "40");
 		// grad.addColorStop(0.75, str(color_b) + "40");
 		// grad.addColorStop(1, str(color_b) + "00");
 		// drawingContext.fillStyle = grad;
 		// ellipse(0, -y_plus, y_size / 5, y_size / 10);
 		// pop();
 	}
 }

class backwardsModule {
 	constructor(xOff, yOff, x, y, speed, unit) {
 		this.xOff = xOff;
 		this.yOff = yOff;
 		this.x = x;
 		this.y = y;
 		this.speed = speed * 1.5;
 		this.unit = unit;
 		this.xDir = -1;
 		this.yDir = -1;
 	} 

 	// Custom method for updating the variables
 	update() {
 		this.x = this.x + this.speed * this.xDir;
 		// this.y = this.y + this.speed * this.yDir;
 		if (this.x >= this.unit+90 || this.x <= -100) {
 			this.xDir *= -1;
 			this.x = this.x + 1 * this.xDir;
 			this.y = this.y + 1 * this.yDir;
 			loop_num++;
 		}
 		if (this.y >= this.unit || this.y <= 0) {
 			this.yDir *= -1;
 			this.y = this.y + 1 * this.yDir;
 		}
 	}

 	// Custom method for drawing the object
 	draw() {
 		noStroke();
 		fill(str(random(colorselect)) + "80");

 		//shadow & highlight
 		drawingContext.shadowColor = "#ffffff33";
 		drawingContext.shadowOffsetX = -1;
 		drawingContext.shadowOffsetY = -1;
 		drawingContext.shadowBlur = 0;
 		drawingContext.shadowColor = "#2f2f2f1a";
 		drawingContext.shadowOffsetX = 1;
 		drawingContext.shadowOffsetY = 1;
 		drawingContext.shadowBlur = 0;

 		//parameters
 		var y_size = this.unit * noise(random(), frameCount * 0.01);
 		var rio = 0.25;
 		var y_plus = random(0, y_size * rio)

 		//mountain
 		stroke(random(darkColors));
 		strokeWeight(0.25);
 		push();
 		translate(this.x + this.xOff, this.yOff - this.y);
 		rotate(-PI);
 		//gradient
 		var color_a = random(colorselect);
 		grad = drawingContext.createLinearGradient(0, 0, 0, y_size);
 		grad.addColorStop(0, str(color_a) + "1a");
 		grad.addColorStop(0.45, str(random(colorselect)) + "40");
 	//	grad.addColorStop(1, str(random(colorselect)) + "80");
 		drawingContext.fillStyle = grad;
 		// rectMode(CENTER);
 		// randomSeed(seed);
 		arc(0, y_plus, y_size / 10, y_size, 0, PI);
 		pop();

 		drawingContext.shadowColor = "#ffffff00";
 		drawingContext.shadowOffsetX = -1;
 		drawingContext.shadowOffsetY = -1;
 		drawingContext.shadowBlur = 0;
 		drawingContext.shadowColor = "#2f2f2f00";
 		drawingContext.shadowOffsetX = 1;
 		drawingContext.shadowOffsetY = 1;
 		drawingContext.shadowBlur = 0;
 		// //circle line
 		// noStroke();
 		// push();
 		// translate(this.xOff + this.x, this.yOff - this.y);
 		// grad = drawingContext.createLinearGradient(0, -y_size / 10 - y_plus, 0, y_size / 10 - y_plus);
 		// grad.addColorStop(0, str(color_a) + "00");
 		// grad.addColorStop(0.25, str(color_a) + "40");
 		// grad.addColorStop(0.75, str(color_b) + "40");
 		// grad.addColorStop(1, str(color_b) + "00");
 		// drawingContext.fillStyle = grad;
 		// ellipse(0, -y_plus, y_size / 5, y_size / 10);
 		// pop();
 	}
 }

 function makeFilter() {
 	randomSeed(seed);
 	// noiseのフィルターをつくる
 	colorMode(HSB, 360, 100, 100, 100);
 	drawingContext.shadowColor = color(0, 0, 2, 2);
 	overAllTexture = createGraphics(windowWidth, windowHeight);
 	overAllTexture.loadPixels();
 	for (var i = 0; i < width; i++) {
 		for (var j = 0; j < height; j++) {
 			overAllTexture.set(
 				i,
 				j,
 				color(0, 10, 40, noise(i / 5, j / 5, (i * j) / 100))
 			);
 		}
 	}
 	overAllTexture.updatePixels();

 }

